theorem MIPStarRE.QPBT.SubLineWitness.avgOver_extendedPointOverlap_ge {params : _root_.MIPStarRE.QPBT.AdmissibleParams}
    {error pointError lineError : ℝ} {setting : _root_.MIPStarRE.QPBT.ProjectiveSetting params error}
    {points : _root_.MIPStarRE.QPBT.CombinedPointsWitness setting pointError}
    (sublines : _root_.MIPStarRE.QPBT.SubLineWitness params) (lines : _root_.MIPStarRE.QPBT.CombinedLinesWitness setting points lineError)
    (first second : _root_.MIPStarRE.QPBT.Placement) (hopposite : first.IsOpposite second) :
    _root_.LIDT.MIPStarRE.LDT.avgOver sublines.D (_root_.MIPStarRE.QPBT.pairedSublineOverlap setting points lines first second) ≤
      _root_.LIDT.MIPStarRE.LDT.avgOver (_root_.MIPStarRE.QPBT.directLinePointDist params.extendedDirectLd)
        (_root_.MIPStarRE.QPBT.extendedPointOverlap setting points lines sublines first second) := by sorry

theorem MIPStarRE.QPBT.SubLineWitness.paired_ordered_overlap_gap_le {params : _root_.MIPStarRE.QPBT.AdmissibleParams}
    {error pointError lineError : ℝ} {setting : _root_.MIPStarRE.QPBT.ProjectiveSetting params error}
    {points : _root_.MIPStarRE.QPBT.CombinedPointsWitness setting pointError}
    (sublines : _root_.MIPStarRE.QPBT.SubLineWitness params) (lines : _root_.MIPStarRE.QPBT.CombinedLinesWitness setting points lineError)
    (first second : _root_.MIPStarRE.QPBT.Placement) :
    |avgOver sublines.D (_root_.MIPStarRE.QPBT.pairedSublineOverlap setting points lines first second) -
      _root_.LIDT.MIPStarRE.LDT.avgOver sublines.D (_root_.MIPStarRE.QPBT.orderedSublineOverlap setting points lines first second)| ≤
        Real.sqrt (4 * pointError) := by sorry

